CREATE TABLE torneos(id INTEGER PRIMARY KEY AUTOINCREMENT, fecha TEXT DEFAULT CURRENT_TIMESTAMP, estado TEXT NOT NULL, campeones TEXT);
CREATE TABLE participantes_torneo(id INTEGER PRIMARY KEY AUTOINCREMENT, torneo_id INTEGER NOT NULL REFERENCES torneos(id), posicion INTEGER NOT NULL, nombre TEXT NOT NULL, UNIQUE(torneo_id,posicion));
CREATE TABLE resultados_torneo(id INTEGER PRIMARY KEY AUTOINCREMENT, torneo_id INTEGER NOT NULL REFERENCES torneos(id), juego TEXT NOT NULL, fase TEXT NOT NULL, participante INTEGER NOT NULL, puntos INTEGER NOT NULL, fecha TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(torneo_id,juego,fase));
